const prev = $('Parse Rubric Output').first().json;
const geminiResp = $input.first().json;

let resumeEvalText = "";
if (geminiResp.candidates && geminiResp.candidates[0]?.content?.parts[0]?.text) {
  resumeEvalText = geminiResp.candidates[0].content.parts[0].text;
} else if (geminiResp.error) {
  resumeEvalText = "Error evaluating resume: " + (geminiResp.error.message || JSON.stringify(geminiResp.error));
} else {
  resumeEvalText = "Unexpected response: " + JSON.stringify(geminiResp);
}

// Robust GitHub username extraction
let username = prev.github_username || "";
if (!username) {
  const match = prev.resume.match(/github\.com\/([a-zA-Z0-9_-]+)/i) || resumeEvalText.match(/github\.com\/([a-zA-Z0-9_-]+)/i);
  if (match && match[1]) {
    username = match[1];
  }
}

// Clean username (handle URLs, @, trailing slashes, query params)
if (username.includes("github.com/")) {
  const parts = username.split("github.com/");
  username = parts[parts.length - 1].split("/")[0].split("?")[0];
}
username = username.replace(/^@/, '').replace(/\/$/, '').trim();

return {
  json: {
    ...prev,
    resume_evaluation: resumeEvalText,
    github_username: username
  }
};

const prev = $('Parse Resume Evaluation').first().json;
const apiData = $input.first().json;

let githubValidationReport = {};

if (apiData.login) {
  githubValidationReport = {
    status: "PASSED",
    username: apiData.login,
    name: apiData.name || "Not provided",
    company: apiData.company || "Not provided",
    location: apiData.location || "Not provided",
    bio: apiData.bio || "Not provided",
    public_repos: apiData.public_repos || 0,
    followers: apiData.followers || 0,
    following: apiData.following || 0,
    created_at: apiData.created_at || "",
    html_url: apiData.html_url || `https://github.com/${prev.github_username}`
  };
} else {
  githubValidationReport = {
    status: "FAILED",
    username: prev.github_username,
    error: apiData.message || "Account not found on GitHub API"
  };
}

return {
  json: {
    ...prev,
    github_validation: githubValidationReport
  }
};

