const geminiResp = $input.first().json;

// Retrieve input data passed into Step 5
const prev = $node["Step 5: VerdictSynthesizer (LLM)"].input.item.json;

let verdictText = "";
if (geminiResp.candidates && geminiResp.candidates[0]?.content?.parts[0]?.text) {
  verdictText = geminiResp.candidates[0].content.parts[0].text;
} else if (geminiResp.error) {
  verdictText = "Error synthesizing verdict: " + (geminiResp.error.message || JSON.stringify(geminiResp.error));
} else {
  verdictText = "Unexpected response: " + JSON.stringify(geminiResp);
}

const decision = "HUMAN_REVIEW_REQUIRED";
const composite_score = "Not calculated";

// Extract Candidate Name
const candidateLine = (prev.resume_evaluation || "").split("\n").find((line) => /CANDIDATE:/i.test(line));
const candidate_name = candidateLine ? candidateLine.replace(/^.*?CANDIDATE:\s*/i, "").replace(/\*/g, "").trim() : "Candidate";

return {
  json: {
    success: Boolean(geminiResp.candidates && geminiResp.candidates[0]?.content?.parts[0]?.text),
    candidate_name,
    decision,
    composite_score,
    summary: {
      rubric: prev.rubric,
      resume_evaluation: prev.resume_evaluation,
      github_validation: prev.github_validation,
      github_evaluation: prev.github_evaluation,
      final_verdict: verdictText
    }
  }
};
